package com.hospital.system.controller; import com.hospital.system.model.Patient; import com.hospital.system.service.PatientService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/patients") public class PatientController {private final PatientService s; public PatientController(PatientService s){this.s=s;} @GetMapping public Object all(@RequestParam(defaultValue="") String q){return s.all(q);} @GetMapping("/{id}") public Patient one(@PathVariable Long id){return s.one(id);} @PostMapping public ResponseEntity<Patient> add(@Valid @RequestBody Patient p){return ResponseEntity.status(201).body(s.add(p));} @PutMapping("/{id}") public Patient update(@PathVariable Long id,@Valid @RequestBody Patient p){return s.update(id,p);} @DeleteMapping("/{id}") public ResponseEntity<Void> del(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();} }
